import { useFrameInjection } from '../context';
import type { EditSlots, FormMode, SaveBarSlotProps } from '../types';

/**
 * shadcn-flavored edit slots. Deliberately NOT FormBody (already themed by seam's
 * ShadcnTheme) or Container (the host owns its Sheet/Dialog) — only the two chrome
 * slots the plain defaults leave bare: the mode Toggle and the SaveBar.
 */

export function ShadcnToggle({
    value,
    onChange,
}: {
    value: FormMode;
    onChange: (m: FormMode) => void;
}) {
    return (
        <div
            data-frame-slot="Toggle"
            role="radiogroup"
            aria-label="Form mode"
            className="mb-4 inline-flex rounded-md border border-border bg-muted p-0.5 text-sm"
        >
            {(['enriched', 'bare'] as FormMode[]).map((mode) => (
                <button
                    key={mode}
                    type="button"
                    role="radio"
                    aria-checked={value === mode}
                    onClick={() => onChange(mode)}
                    className={`rounded px-3 py-1 capitalize transition-colors ${
                        value === mode
                            ? 'bg-background text-foreground shadow-sm'
                            : 'text-muted-foreground hover:text-foreground'
                    }`}
                >
                    {mode}
                </button>
            ))}
        </div>
    );
}

// B1 faces (owner-review 18): the inline base that keeps one label visible without motion.css.
const FACES = { display: 'inline-grid' } as const;
const FACE_ON = { gridArea: '1 / 1' } as const;
const FACE_OFF = { gridArea: '1 / 1', opacity: 0, pointerEvents: 'none' } as const;


export function ShadcnSaveBar({ saving, canSubmit, readOnly, onSave, onCancel }: SaveBarSlotProps) {
    const { primitives } = useFrameInjection();
    const { Button } = primitives;
    return (
        <div
            data-frame-slot="SaveBar"
            // Sticky one-primary-CTA footer: Save stays reachable at the bottom of a
            // scrolling edit panel (the drawer's overflow container is the scroll
            // parent). A translucent, blurred backing keeps fields legible as they
            // scroll under it. Cancel is visually subordinate (ghost); Save is primary.
            className="sticky bottom-0 z-10 -mx-1 mt-6 flex justify-end gap-2 border-t border-border bg-background/95 px-1 py-3 backdrop-blur supports-[backdrop-filter]:bg-background/80"
        >
            {onCancel ? (
                <Button type="button" variant="ghost" onClick={onCancel} data-frame-action="cancel">
                    Cancel
                </Button>
            ) : null}
            {!readOnly ? (
                <Button
                    type="button"
                    disabled={saving || !canSubmit}
                    onClick={onSave}
                    data-frame-action="save"
                >
                    {/* B1: both labels in one cell, so Save holds its width while saving. Stacking and hiding
                        are inline (a host without motion.css still shows one label); motion.css adds the fade. */}
                    <span className="motion-faces" style={FACES}>
                        <span
                            className="motion-face"
                            style={saving ? FACE_OFF : FACE_ON}
                            data-face="idle"
                            data-on={!saving}
                            aria-hidden={saving || undefined}
                        >
                            Save
                        </span>
                        <span
                            className="motion-face"
                            style={saving ? FACE_ON : FACE_OFF}
                            data-face="saving"
                            data-on={saving}
                            aria-hidden={!saving || undefined}
                        >
                            Saving…
                        </span>
                    </span>
                </Button>
            ) : null}
        </div>
    );
}

/** Spread into an EditShell's `slots` for a shadcn-native editor; override keys after. */
export const shadcnEditSlots = {
    Toggle: ShadcnToggle,
    SaveBar: ShadcnSaveBar,
} satisfies Partial<EditSlots>;
